import Button from '@jetbrains/ring-ui-built/components/button/button'
import {memo, useCallback, useMemo, useState} from 'react'
import type {MouseEvent} from 'react'

import type {TypedValue} from '../../../../../../services/rest'
import {restApi} from '../../../../../../services/rest'
import type {BuildId, BuildTypeId, TestId, TestOccurrenceId} from '../../../../../../types'
import {emptyArray} from '../../../../../../utils/empty'
import TestMetadataItem from '../../../TestMetadataIcon/TestMetadataPopup/TestMetadataItem'
import {showTestMetadataGraph} from '../../../Tests.actions'
import {getTestOccurrenceMetadataArg} from '../../../Tests.rest'

import TestMetadataMedia from './TestMetadataMedia/TestMetadataMedia'

import styles from './TestMetadata.module.css'

import {useAppDispatch} from 'src/hooks/react-redux'

const LIMIT_VISIBLE_BY_DEFAULT = 3

type Props = {
  className?: string
  buildId: BuildId | null | undefined
  buildTypeId: BuildTypeId | null | undefined
  testOccurrenceId: TestOccurrenceId | null | undefined
  testId: TestId | null | undefined
}

function TestMetadata({className, buildTypeId, buildId, testOccurrenceId, testId}: Props) {
  const dispatch = useAppDispatch()

  const {metadataList} = restApi.endpoints.getTestOccurrence.useQuery(
    getTestOccurrenceMetadataArg(testOccurrenceId),
    {
      selectFromResult: ({data}) => ({
        metadataList: data?.metadata?.typedValues ?? (emptyArray as TypedValue[]),
      }),
    },
  )

  const showTestMetadataGraphHandler = useCallback(
    (escapedName: string | undefined, {currentTarget}: MouseEvent<any>) =>
      testId != null &&
      buildId != null &&
      escapedName != null &&
      dispatch(showTestMetadataGraph(currentTarget, testId, buildId, escapedName, buildTypeId)),
    [dispatch, testId, buildId, buildTypeId],
  )

  const mediaMetadataList = useMemo(
    () => metadataList.filter(metadata => metadata.type === 'image' || metadata.type === 'video'),
    [metadataList],
  )
  const otherMetadataList = useMemo(
    () => metadataList.filter(metadata => metadata.type !== 'image' && metadata.type !== 'video'),
    [metadataList],
  )

  const [showMore, setShowMore] = useState(false)
  const toggleShowMore = useCallback(() => setShowMore(true), [setShowMore])

  return metadataList.length > 0 ? (
    <div className={className}>
      {mediaMetadataList.length > 0 ? (
        <TestMetadataMedia
          buildTypeId={buildTypeId}
          buildId={buildId}
          metadataList={mediaMetadataList}
        />
      ) : null}
      <div>
        {otherMetadataList
          .slice(0, showMore ? otherMetadataList.length : LIMIT_VISIBLE_BY_DEFAULT)
          .map(metadata => (
            <div className={styles.metadataItem} key={metadata.name}>
              <TestMetadataItem
                buildTypeId={buildTypeId}
                buildId={buildId}
                metadata={metadata}
                showTestMetadataGraph={showTestMetadataGraphHandler}
              />
            </div>
          ))}
      </div>
      {otherMetadataList.length > LIMIT_VISIBLE_BY_DEFAULT && !showMore && (
        <Button className={styles.toggleOtherButton} onClick={toggleShowMore} inline>
          {`Show ${otherMetadataList.length - LIMIT_VISIBLE_BY_DEFAULT} more`}
        </Button>
      )}
    </div>
  ) : null
}

export default memo(TestMetadata)
