import 'yet-another-react-lightbox/styles.css'
import 'yet-another-react-lightbox/plugins/captions.css'

import Button from '@jetbrains/ring-ui-built/components/button/button'
import {memo, useCallback, useState} from 'react'
import Lightbox from 'yet-another-react-lightbox'
import Captions from 'yet-another-react-lightbox/plugins/captions'
import Fullscreen from 'yet-another-react-lightbox/plugins/fullscreen'
import Video from 'yet-another-react-lightbox/plugins/video'

import type {TypedValue} from '../../../../../../../services/rest'
import type {BuildId, BuildTypeId} from '../../../../../../../types'
import Icon from '../../../../../../common/Icon/Icon'
import MiddleEllipsis from '../../../../../../common/MiddleEllipsis/MiddleEllipsis'
import ValueToClickAction from '../../../../../../common/ValueToClickAction/ValueToClickAction'
import {
  getFileName,
  getSrcLink,
  getName,
} from '../../../../TestMetadataIcon/TestMetadataPopup/TestMetadataPopup.utils'

import {getSlides} from './TestMetadataMedia.utils'

import styles from './TestMetadataMedia.module.css'

const LIMIT_VISIBLE_BY_DEFAULT = 3
const LIGHTBOX_ANIMATION_OPTIONS = {fade: 0, swipe: 0}
const LIGHTBOX_CONTROLLER_OPTIONS = {closeOnBackdropClick: true}
const LIGHTBOX_VIDEO_OPTIONS = {autoPlay: true}
const LIGHTBOX_PLUGINS = [Video, Fullscreen, Captions]

type Props = {
  className?: string
  buildId: BuildId | null | undefined
  buildTypeId: BuildTypeId | null | undefined
  metadataList: TypedValue[]
}

function TestMetadataMedia({className, buildId, buildTypeId, metadataList}: Props) {
  const [showMoreImages, setShowMoreImages] = useState(false)
  const [viewerOpen, setViewerOpen] = useState(false)
  const [selectedImage, setSelectedImage] = useState(0)

  const openLightbox = useCallback((index: number) => {
    setSelectedImage(index)
    setViewerOpen(true)
  }, [])
  const closeLightbox = useCallback(() => {
    setViewerOpen(false)
    setSelectedImage(0)
  }, [])

  const toggleShowMoreImages = useCallback(() => setShowMoreImages(true), [setShowMoreImages])
  const slides = getSlides(metadataList, buildTypeId, buildId)

  const renderMediaItem = useCallback(
    (metadata: TypedValue, index: number) => {
      const name = getName(metadata)
      const fileName = getFileName(metadata)
      const fileUrl = getSrcLink(metadata.value, buildTypeId, buildId)
      const isVideo = metadata.type === 'video'

      return (
        <ValueToClickAction
          value={index}
          key={metadata.name}
          onClick={openLightbox}
          child={
            <button type="button" className={styles.mediaButton}>
              <div
                className={styles.media}
                title={`${name != null ? `Name: ${name}\n` : ''}${
                  fileName != null ? `File name: ${fileName}` : ''
                }`}
                style={isVideo ? {} : {backgroundImage: `url("${fileUrl}")`}}
              >
                {isVideo && (
                  <>
                    <div className={styles.playButton}>
                      <Icon name="play" />
                    </div>
                    {/* eslint-disable-next-line jsx-a11y/media-has-caption */}
                    <video
                      className={styles.videoPreview}
                      src={getSrcLink(metadata.value, buildTypeId, buildId)}
                    />
                  </>
                )}
              </div>
              <div className={styles.fileName}>
                <MiddleEllipsis tailLength={8}>{name != null ? name : fileName}</MiddleEllipsis>
              </div>
            </button>
          }
        />
      )
    },
    [openLightbox, buildTypeId, buildId],
  )

  return metadataList.length > 0 ? (
    <div className={className}>
      <div className={styles.mediaItems}>
        {metadataList
          .slice(0, showMoreImages ? metadataList.length : LIMIT_VISIBLE_BY_DEFAULT)
          .map(renderMediaItem)}
        {metadataList.length > LIMIT_VISIBLE_BY_DEFAULT && !showMoreImages && (
          <div>
            <Button className={styles.toggleMediaButton} onClick={toggleShowMoreImages} inline>
              {`+ ${metadataList.length - LIMIT_VISIBLE_BY_DEFAULT} more`}
            </Button>
          </div>
        )}
      </div>
      <Lightbox
        className={styles.lightbox}
        animation={LIGHTBOX_ANIMATION_OPTIONS}
        slides={slides}
        open={viewerOpen}
        index={selectedImage}
        close={closeLightbox}
        plugins={LIGHTBOX_PLUGINS}
        controller={LIGHTBOX_CONTROLLER_OPTIONS}
        video={LIGHTBOX_VIDEO_OPTIONS}
        render={{
          buttonPrev: slides.length <= 1 ? () => null : undefined,
          buttonNext: slides.length <= 1 ? () => null : undefined,
        }}
      />
    </div>
  ) : null
}

export default memo(TestMetadataMedia)
