import classNames from 'classnames'
import {memo} from 'react'

import {useIsAutodetectTimeZone} from '../../../../../hooks/useIsAutodetectTimeZone'
import {displayDate} from '../../../../../utils/dateTimeUtils'
import BuildBranch from '../../../../common/BranchLabel/BuildBranchLabel.container'
import BuildPathAndStatus from '../../../../common/BuildPathAndStatus/BuildPathAndStatus'
import {getKeyForBuildLogData} from '../../../BuildLog/BuildLog.utils'
import BuildLogPreview from '../../../BuildLog/BuildLogPreview/BuildLogPreview.container'
import BuildChangesDropdown from '../../../Changes/BuildChangesDropdown/BuildChangesDropdown'
import TestFlakyLabel from '../../TestFlakyLabel/TestFlakyLabel'

import type {OwnProps} from './BuildTestTab.types'
import TestMetadata from './TestMetadata/TestMetadata'

import styles from './BuildTestTab.module.css'

function BuildTestTab({
  className,
  buildId,
  lastReadyTestOccurrence,
  startDate,
  withBuildInfo,
  isReady,
}: OwnProps) {
  const isAutodetectTimeZone = useIsAutodetectTimeZone()
  const {build, test, logAnchor, id: testOccurrenceId} = lastReadyTestOccurrence ?? {}
  const testBuildId = build?.id
  const testBuildTypeId = build?.buildTypeId
  const testId = test?.id
  return lastReadyTestOccurrence != null && testBuildId != null && testId != null ? (
    <div
      className={classNames(className, {
        [styles.withOverlay]: !isReady,
      })}
    >
      {withBuildInfo === true && (
        <div className={styles.buildInfo}>
          <BuildPathAndStatus
            className={styles.buildPath}
            buildTypeId={testBuildTypeId}
            buildId={testBuildId}
            linkClassName={styles.buildPathLinks}
          />
          <BuildBranch className={styles.buildBranch} buildId={testBuildId} />
          <BuildChangesDropdown className={styles.buildChanges} buildId={testBuildId} />
          {startDate != null && (
            <span className={styles.startDate}>{`${displayDate(
              startDate,
              isAutodetectTimeZone,
              true,
            )}`}</span>
          )}
        </div>
      )}
      <TestFlakyLabel
        className={styles.flakyLabel}
        buildId={buildId}
        testId={testId}
        withDescription
      />
      <TestMetadata
        className={styles.metadata}
        buildId={testBuildId}
        buildTypeId={build?.buildTypeId}
        testOccurrenceId={testOccurrenceId}
        testId={testId}
      />
      <BuildLogPreview
        className={styles.buildLog}
        buildId={testBuildId}
        focusLine={logAnchor}
        expandLine={logAnchor}
        buildLogKey={getKeyForBuildLogData({
          type: 'test',
          id: lastReadyTestOccurrence.id,
        })}
      />
    </div>
  ) : null
}

export default memo(BuildTestTab)
