import {skipToken} from '@reduxjs/toolkit/query'
import {useRef, memo, useEffect} from 'react'

import {fetchBuildsData} from '../../../../../actions/builds'
import {useFetchEffect} from '../../../../../hocs/withEffect'
import {getBuild, getExtensionEndpoint} from '../../../../../selectors'
import {restApi} from '../../../../../services/rest'
import {createRefetchableSubscription} from '../../../../../utils/refetchable'
import {subscribeOnBuildTypeEvents} from '../../../../../utils/subscriber'
import * as SubscriptionEvents from '../../../../../utils/subscriptionEvents'
import {useSequenceLoaderReadyHandler} from '../../../../common/SequenceLoader/SequenceLoader.hooks'
import {fetchBuildLogMessages} from '../../../BuildLog/BuildLog.actions'
import {getBuildLogMessagesReady} from '../../../BuildLog/BuildLog.selectors'
import {getKeyForBuildLogData} from '../../../BuildLog/BuildLog.utils'
import {getTestOccurenceArg, getTestOccurrenceMetadataArg} from '../../Tests.rest'
import {getBaseTestOccurrence, getFlakyTestData} from '../../Tests.selectors'

import BuildTestTab from './BuildTestTab'
import type {ContainerOwnProps} from './BuildTestTab.types'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

const events = [
  SubscriptionEvents.BUILD_STARTED,
  SubscriptionEvents.BUILD_CHANGES_LOADED,
  SubscriptionEvents.BUILD_FINISHED,
  SubscriptionEvents.BUILD_INTERRUPTED,
  SubscriptionEvents.BUILD_REMOVED,
  SubscriptionEvents.BUILD_TAGS_CHANGED,
]

function BuildTestTabContainer(props: ContainerOwnProps) {
  const {buildId, testOccurrenceId} = props

  const dispatch = useAppDispatch()
  const oldTestOccurrenceIdRef = useRef(testOccurrenceId) // initial value

  const buildLogKey = getKeyForBuildLogData({type: 'test', id: testOccurrenceId})
  const flakyTestsEndpoint = useAppSelector(state => getExtensionEndpoint(state, 'flaky'))
  const testOccurrence = useAppSelector(state => getBaseTestOccurrence(state, testOccurrenceId))

  const {test, build: testOccurrenceBuild, logAnchor} = testOccurrence ?? {}
  const {id: testOccurrenceBuildId, buildType: testOccurrenceBuildType} = testOccurrenceBuild ?? {}
  const testOccurrenceBuildTypeIdInternalId = testOccurrenceBuildType?.internalId
  const {id: testId} = test ?? {}

  const isReadyTestOccurrence = testOccurrence != null
  const isReadyBuildLogMessages = useAppSelector(state =>
    getBuildLogMessagesReady(state, buildLogKey),
  )
  const {isReadyTestOccurrenceMetadata} = restApi.endpoints.getTestOccurrence.useQuery(
    getTestOccurrenceMetadataArg(testOccurrenceId),
    {selectFromResult: ({data}) => ({isReadyTestOccurrenceMetadata: data != null})},
  )
  const isReadyFlakyTestData = useAppSelector(state =>
    flakyTestsEndpoint != null ? getFlakyTestData(state, buildId, testId) != null : true,
  )
  const isReadyBuild = useAppSelector(state => getBuild(state, testOccurrenceBuildId) != null)

  const isReady =
    isReadyBuild &&
    isReadyTestOccurrence &&
    isReadyTestOccurrenceMetadata &&
    isReadyBuildLogMessages &&
    isReadyFlakyTestData

  if (isReady) {
    oldTestOccurrenceIdRef.current = testOccurrenceId
  }

  const lastReadyTestOccurrenceId = !isReady ? oldTestOccurrenceIdRef.current : testOccurrenceId
  const lastReadyTestOccurrence = useAppSelector(state =>
    getBaseTestOccurrence(state, lastReadyTestOccurrenceId),
  )
  const build = useAppSelector(state => getBuild(state, lastReadyTestOccurrence?.build?.id))
  const {startDate} = build ?? {}

  restApi.endpoints.getTestOccurrenceNormalized.useQuerySubscription(
    testOccurrenceId != null
      ? getTestOccurenceArg(testOccurrenceId, {
          withNewFailure: true,
          withMetadataCount: true,
          withNextFixed: true,
          withFirstFailed: true,
          withMuteInfo: true,
          withInvestigationInfo: true,
        })
      : skipToken,
  )

  restApi.endpoints.getFlakyTests.useQuerySubscription(
    buildId != null &&
      testId != null &&
      testOccurrenceBuildTypeIdInternalId != null &&
      flakyTestsEndpoint != null
      ? {
          buildId,
          tests: [{testName: testId, buildTypeId: testOccurrenceBuildTypeIdInternalId}],
          endpoint: flakyTestsEndpoint.endpoint,
        }
      : skipToken,
  )

  useEffect(() => {
    if (
      isReadyTestOccurrence &&
      !isReadyBuildLogMessages &&
      logAnchor != null &&
      testOccurrenceBuildId != null
    ) {
      dispatch(
        fetchBuildLogMessages({
          buildId: testOccurrenceBuildId,
          buildLogKey,
          options: {
            logAnchor: Number(logAnchor),
            expandState: [Number(logAnchor)],
            testOccurrenceId,
            count: 1000,
          },
        }),
      )
    }
  }, [
    buildLogKey,
    dispatch,
    isReadyBuildLogMessages,
    isReadyTestOccurrence,
    logAnchor,
    testOccurrenceBuildId,
    testOccurrenceId,
  ])

  useFetchEffect(
    () =>
      testOccurrenceBuildTypeIdInternalId != null && testOccurrenceBuildId != null
        ? createRefetchableSubscription(
            () =>
              dispatch(
                fetchBuildsData({
                  locator: `id:${testOccurrenceBuildId}`,
                  requestOptions: {
                    withRunningInfo: true,
                    withPipelineRuns: true,
                    withAnchorBuild: true,
                  },
                }),
              ),
            handler =>
              subscribeOnBuildTypeEvents(testOccurrenceBuildTypeIdInternalId, events, handler),
          )
        : undefined,
    [dispatch, isReadyBuild, testOccurrenceBuildId, testOccurrenceBuildTypeIdInternalId],
  )

  useSequenceLoaderReadyHandler(isReady)

  return (
    <BuildTestTab
      lastReadyTestOccurrence={lastReadyTestOccurrence}
      startDate={startDate}
      isReady={isReady}
      {...props}
    />
  )
}

export default memo(BuildTestTabContainer)
