import type {Slide} from 'yet-another-react-lightbox'

import type {TypedValue} from '../../../../../../../services/rest'
import type {BuildId, BuildTypeId} from '../../../../../../../types'
import {getSrcLink} from '../../../../TestMetadataIcon/TestMetadataPopup/TestMetadataPopup.utils'

export const getSlides = (
  metadataList: TypedValue[],
  buildTypeId: BuildTypeId | null | undefined,
  buildId: BuildId | null | undefined,
) =>
  metadataList.map(metadata => {
    const src = getSrcLink(metadata.value, buildTypeId, buildId)
    const description = metadata.value ?? ''

    if (metadata.type === 'video') {
      return {
        type: 'video',
        sources: [
          {
            src,
            type: 'video/mp4',
          },
        ],
        description,
      }
    }
    return {src, description}
  }) as Slide[]
