import {memo, useMemo} from 'react'

import type {BuildId, TestId} from '../../../../types'
import {getFlakyTestData} from '../Tests.selectors'

import styles from './TestFlakyLabel.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  buildId: BuildId | null | undefined
  testId: TestId | null | undefined
  withDescription?: boolean
}

function TestFlakyLabel({className, buildId, testId, withDescription}: Props) {
  const flakyTestData = useAppSelector(state => getFlakyTestData(state, buildId, testId))
  const descriptions = flakyTestData?.descriptions?.join('\u00a0') ?? ''
  const label = useMemo(
    () => (
      <span className={styles.label} title={descriptions}>
        <span className={styles.character}>{'f'}</span>
        <span className={styles.character}>{'l'}</span>
        <span className={styles.character}>{'a'}</span>
        <span className={styles.character}>{'k'}</span>
        <span className={styles.character}>{'y'}</span>
      </span>
    ),
    [descriptions],
  )
  return flakyTestData?.isFlaky === true ? (
    <div className={className} data-test-build-test-flaky>
      {withDescription === true ? (
        <>
          <span className={styles.title}>
            {`Test looks `}
            {label}
            {'.'}
          </span>
          <span className={styles.descriptions}>{descriptions}</span>
        </>
      ) : (
        label
      )}
    </div>
  ) : null
}

export default memo(TestFlakyLabel)
